/* Device speech + on-demand public dictionary recordings. Never calls the AI API. */
const Pronunciation=(()=>{
 const STORE='word-pronunciation-v1';let speech=null,player=null,blobURL=null,epoch=0,refreshVoices=null,speechWatchdog=null;
 const prefKey=typeof Profiles!=='undefined'?Profiles.key('pronunciation'):'cet6-pronunciation';let accent='en-US';try{const saved=localStorage.getItem(prefKey);if(['en-US','en-GB'].includes(saved))accent=saved;}catch{}
 function chooseVoice(voices,language,offline=false){const english=voices.filter(v=>/^en(?:[-_]|$)/i.test(v.lang)&&(!offline||v.localService===true));return english.find(v=>v.lang.replace('_','-').toLowerCase()===language.toLowerCase()&&v.localService)||english.find(v=>v.lang.replace('_','-').toLowerCase()===language.toLowerCase())||english.find(v=>v.localService)||english[0]||null;}
 function safeAudio(url){try{const u=new URL(url,'https://dictionaryapi.dev');return u.protocol==='https:'&&!u.username&&!u.password&&['api.dictionaryapi.dev','ssl.gstatic.com'].includes(u.hostname)?u.href:null;}catch{return null;}}
 function audioAccent(url){return /(?:[-_]uk|_gb_)/i.test(url)?'en-GB':/(?:[-_]us|_us_)/i.test(url)?'en-US':'unknown';}
 function pickAudio(entries,language){const found=(Array.isArray(entries)?entries:[]).flatMap(e=>Array.isArray(e.phonetics)?e.phonetics:[]).map(p=>safeAudio(p.audio||'')).filter(Boolean);return found.find(url=>audioAccent(url)===language)||found[0]||null;}
 function stop(){if(speechWatchdog)clearTimeout(speechWatchdog);speechWatchdog=null;epoch++;try{window.speechSynthesis?.cancel();}catch{}speech=null;if(player){player.pause();player.removeAttribute('src');player.load();player.hidden=true;player=null;}if(blobURL){URL.revokeObjectURL(blobURL);blobURL=null;}}
 function say(text,rate,status,onFailure){stop();const synth=window.speechSynthesis;if(!synth||typeof SpeechSynthesisUtterance==='undefined'){status('设备未提供英语朗读，尝试词典录音');return false;}
  let voice;try{voice=chooseVoice(synth.getVoices(),accent,!navigator.onLine);}catch{}
  if(!voice){status('设备没有可用英语声音，尝试词典录音');return false;}
  const id=epoch;const utter=new SpeechSynthesisUtterance(text);speech=utter;utter.lang=voice.lang;utter.voice=voice;utter.rate=rate;utter.volume=1;
  const origin=voice.localService?'本地设备语音':'设备在线语音';const fallback=voice.lang.replace('_','-').toLowerCase()!==accent.toLowerCase()?' · 所选口音不可用，使用 '+voice.lang:'';
  utter.onstart=()=>{clearTimeout(speechWatchdog);speechWatchdog=null;if(id===epoch)status(origin+' · 正在朗读'+fallback);};utter.onend=()=>{clearTimeout(speechWatchdog);speechWatchdog=null;if(id===epoch){speech=null;status(origin+' · 朗读结束'+fallback);}};utter.onerror=()=>{clearTimeout(speechWatchdog);speechWatchdog=null;if(id===epoch){speech=null;if(onFailure)onFailure();else status('设备朗读未完成，请点击词典音频重试');}};
  try{synth.cancel();synth.resume();speechWatchdog=setTimeout(()=>{if(id===epoch&&speech===utter&&onFailure)onFailure();},3000);synth.speak(utter);return true;}catch{status('设备朗读不可用，尝试词典录音');return false;}
 }
 async function recording(word,language){const key=new URL('./_word-pronunciation/'+encodeURIComponent(word.toLowerCase())+'-'+language,location.href).href;let cache=null;try{cache=await caches.open(STORE);const stored=await cache.match(key);if(stored)return {blob:await stored.blob(),accent:stored.headers.get('X-Accent')||'unknown',cached:true,provider:stored.headers.get('X-Provider')||'Free Dictionary API'};}catch{}
  // Try the website's published copy before accessing a foreign dictionary host.
  try{const manifestResponse=await fetch(new URL('./word-audio.json',location.href).href,{signal:AbortSignal.timeout(3000)});if(manifestResponse.ok){const manifest=await manifestResponse.json(),entry=manifest.entries?.[word.toLowerCase()];if(entry&&/^[a-f0-9]{20}\.mp3$/.test(entry.file)){const response=await fetch(new URL('./word-audio/'+entry.file,location.href).href,{signal:AbortSignal.timeout(8000)});if(response.ok){const blob=await response.blob();if(blob.size&&blob.size<=1000000&&/^audio\//i.test(blob.type)){if(cache){try{await cache.put(key,new Response(blob,{headers:{'Content-Type':blob.type,'X-Accent':entry.accent||'unknown','X-Provider':'Website / Free Dictionary API','X-Source':entry.source,'X-License':encodeURIComponent(JSON.stringify(entry.license))}}));const keys=await cache.keys();for(const old of keys.slice(0,Math.max(0,keys.length-40)))await cache.delete(old);}catch{}}return {blob,accent:entry.accent||'unknown',cached:false,provider:'本站录音 · Free Dictionary API',source:entry.source,license:entry.license};}}}}}catch{}
  if(!navigator.onLine)throw Error('离线且此词音频尚未下载');
  const res=await fetch('https://api.dictionaryapi.dev/api/v2/entries/en/'+encodeURIComponent(word),{signal:AbortSignal.timeout(8000)});if(!res.ok)throw Error('词典未提供此词音频');const entries=await res.json();const url=pickAudio(entries,language);if(!url)throw Error('此词暂无词典录音');
  const sound=await fetch(url,{signal:AbortSignal.timeout(10000)});if(!sound.ok)throw Error('词典音频下载失败');if(Number(sound.headers.get('content-length')||0)>1000000)throw Error('音频过大');const blob=await sound.blob();if(!blob.size||blob.size>1000000)throw Error('音频大小无效');if(!/^(audio\/|application\/octet-stream)/i.test(blob.type))throw Error('返回的不是音频');
  const actual=audioAccent(url);if(cache){try{await cache.put(key,new Response(blob,{headers:{'Content-Type':blob.type,'X-Accent':actual,'X-Source':url,'X-License':encodeURIComponent(JSON.stringify(entries[0]?.license||null))}}));const keys=await cache.keys();for(const old of keys.slice(0,Math.max(0,keys.length-40)))await cache.delete(old);}catch{}}
  return {blob,accent:actual,cached:false};
 }
 function html(){return '<section aria-label="单词发音"><div class="row"><label for="wordAccent">发音口音</label><select id="wordAccent" style="width:auto"><option value="en-US">美式英语</option><option value="en-GB">英式英语</option></select><button id="wordSpeak">🔊 单词发音</button><button id="wordSlow">慢速发音</button><button id="wordDictionary">词典音频</button></div><p id="wordAudioStatus" class="meta" role="status">设备英语朗读；词典音频首次需联网，成功下载后缓存最近40条。发音不调用 AI API。<a href="word-audio.json" target="_blank" rel="noopener">录音覆盖与来源授权</a></p><audio id="wordRecording" controls hidden preload="none"></audio></section>';}
 function bind(word){const statusNode=document.getElementById('wordAudioStatus');if(!statusNode)return;const status=text=>{if(statusNode.isConnected)statusNode.textContent=text;};const selector=document.getElementById('wordAccent');selector.value=accent;
  selector.onchange=()=>{stop();accent=selector.value;try{localStorage.setItem(prefKey,accent);}catch{}status('已选择'+(accent==='en-US'?'美式':'英式')+'英语；点击播放');};
  async function playDictionary(rate=1){stop();const id=epoch;status('正在读取词典音频…');try{const found=await recording(word,accent);if(id!==epoch||!statusNode.isConnected)return;blobURL=URL.createObjectURL(found.blob);player=document.getElementById('wordRecording');player.src=blobURL;player.hidden=false;player.playbackRate=rate;player.preservesPitch=true;if('webkitPreservesPitch' in player)player.webkitPreservesPitch=true;const fallback=found.accent!==accent?' · 录音口音与所选不同或未标明':'';status((found.provider||'Free Dictionary API')+' · '+(found.cached?'本地缓存':'已取得录音')+fallback+' · 授权以来源条目为准');player.onerror=()=>status('录音无法播放，请检查音量与浏览器音频权限');try{await player.play();}catch{status('音频已准备好，请点击下方播放器播放'+fallback);}}catch(e){if(id===epoch)status('未能取得发音：'+e.message+'。设备语音与词典录音均可能受浏览器或网络限制。');}}
  function play(rate){if(!say(word,rate,status,()=>playDictionary(rate)))return playDictionary(rate);}
  document.getElementById('wordSpeak').onclick=()=>play(1);document.getElementById('wordSlow').onclick=()=>play(0.75);document.getElementById('wordDictionary').onclick=()=>playDictionary(1);
  refreshVoices=()=>{if(!statusNode.isConnected)return;let voice;try{voice=chooseVoice(window.speechSynthesis?.getVoices()||[],accent,!navigator.onLine);}catch{}if(voice&&statusNode.textContent.includes('未提供英语声音'))status('英语声音已就绪，点击单词发音即可播放');};
  let ready;try{ready=chooseVoice(window.speechSynthesis?.getVoices()||[],accent,!navigator.onLine);}catch{}if(!ready)status('当前设备未提供英语声音；点击发音将自动尝试本站或词典录音');
 }
 try{window.speechSynthesis?.getVoices();}catch{}
 window.speechSynthesis?.addEventListener?.('voiceschanged',()=>refreshVoices?.());
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});window.addEventListener('pagehide',stop);
 return {html,bind,stop,chooseVoice,pickAudio,safeAudio,recording,say};
})();
